def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

# Alternatively, using prime factorization for potentially larger numbers, 
# although for k <= 30, direct checking is fine. Let's stick to factorization 
# as it's generally more robust for divisor counting.

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_divisors_factorization(n):
    """Calculates the number of positive divisors using prime factorization."""
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

solutions = []
for k in range(1, 31):
    N = 2 * (k**3)
    num_divs_N = count_divisors_factorization(N)
    target = 2 * k

    if num_divs_N == target:
        solutions.append(k)

print("Solutions found (k <= 30):", solutions)

